insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 4, 1, '{"place":"Under the Kiln, then Ashcombe","narrated":false,"tone":"wry","cupNight":false,"opener":"Count yourselves. I will, too.","forkA":"He had help in the room.","forkB":"He didn''t need any.","callback":"Every one of them you''ve fought has run at the first gap. Tonight one stood among you with a blade and cut only rope.","nudge":"{friend:Craft}, the ropes were cut clean in the dark. His own hand, or another''s?","riddle":{"q":"What can you break without ever touching it?","a":"a promise","quip":"Careful what you hand out.","accept":["a promise","promise"],"maxTries":3},"leads":[{"id":"4-1-1","place":"the passage none of you had noticed","actions":[{"attr":"Agility","verb":"go a few steps in, without a lamp"},{"attr":"Intellect","verb":"stand in its mouth and take stock"}],"clueTitle":"The snuffed wick","clueText":"A few steps into the passage the air smells of a wick just put out. None of your lamps has been in there.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-2","place":"the place where he knelt","actions":[{"attr":"Aim","verb":"pace it out from the passage"},{"attr":"Intellect","verb":"work out what he could reach from there"}],"clueTitle":"Three paces","clueText":"Where he knelt is three paces from the passage mouth, in the corner your lamps lit least.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-3","place":"the ropes on the stone","actions":[{"attr":"Craft","verb":"lay the cut ends side by side"},{"attr":"Might","verb":"pick them up and test each one"}],"clueTitle":"The same side","clueText":"Every rope is cut a finger''s width from its knot, and every cut is on the same side.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"To hold what needed five.\"* What needed holding, and what is the last lock?","weekQuestion":"What do they need Joss for?","pull":"*Already with us.* Joss is not waiting to be taken.\n\n**A blade within arm''s reach, in the dark, and it cut rope. Why are you still alive? The north road, at first light.**"}'::jsonb),
('dark-moon', 1, 4, 2, '{"place":"The north road","narrated":false,"tone":"wry","cupNight":true,"opener":"Cold road. Put your hands round that cup.","forkA":"The box matters more than the swords.","forkB":"The swords are the real message.","callback":"The carter''s coin has the king''s face scraped off. Meira wrote that every record of him had been scraped clean.","nudge":"{friend:Intellect}, who scrapes a face off a coin?","riddle":{"q":"What has a head and a tail but no body?","a":"a coin","quip":"Someone scrubbed a face off this one.","accept":["a coin","coin"],"maxTries":3},"leads":[{"id":"4-2-1","place":"the carter, watering his horses","actions":[{"attr":"Charm","verb":"let him run on about the riders"},{"attr":"Intellect","verb":"ask how the four rode"}],"clueTitle":"Every eye on the cart","clueText":"The carter says the four never spoke to each other, and never once looked at the road or the lake. Every eye stayed on the cart.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-2","place":"the men in the shallows","actions":[{"attr":"Charm","verb":"sit down in the water with them"},{"attr":"Intellect","verb":"ask what made them let it pass"}],"clueTitle":"Blades bare","clueText":"They say the four came through the ford with their blades bare across their saddles, in full daylight, and did not slow down.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-3","place":"the ruts going north","actions":[{"attr":"Aim","verb":"follow them as far as the light lets you"},{"attr":"Craft","verb":"read where they could have turned off"}],"clueTitle":"The open road","clueText":"Their ruts keep to the open road the whole way, past every shepherd''s hut. A sheep-path along the ridge would have hidden them from all of it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"The fifth had no element at all.\"* What could it be, if it is not earth, wind, water or fire?","weekQuestion":"What do they need Joss for?","pull":"**Four armed men for one small box, riding away from the boy. What is in it? Reedham, by noon tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 3, '{"place":"Reedham","narrated":false,"tone":"quiet","cupNight":false,"opener":"A lamp in a window at noon. Somebody has kept it lit for eight nights.","forkA":"They''re waiting for the right night.","forkB":"They''re waiting for the right child.","callback":"In Ashcombe a baby born when the moon goes out is given a chip of black glass. In Reedham every window is lit for one.","nudge":"{friend:Craft}, what does a skiff tell you about its owner?","riddle":{"q":"What gets wetter the more it dries?","a":"a towel","quip":"Hang it by the fire.","accept":["a towel","towel"],"maxTries":3},"leads":[{"id":"4-3-1","place":"the fisherman on the shingle","actions":[{"attr":"Charm","verb":"help him with his nets and listen"},{"attr":"Intellect","verb":"ask what he hears at night"}],"clueTitle":"The oars at dusk","clueText":"On the shingle the fisherman says he hears oars out on the lake every night, at the same hour, just after dusk. He has never gone to look.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-2","place":"the lane up from the water","actions":[{"attr":"Aim","verb":"walk the lane up from the shingle"},{"attr":"Intellect","verb":"look at every door you pass"}],"clueTitle":"One door","clueText":"Small dark spots of lamp-oil stain the stones of the lane, a pace apart. They go up to her door and back, and to no other door.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-3","place":"the tower''s lowest window","actions":[{"attr":"Agility","verb":"climb up to the sill from the skiff"},{"attr":"Aim","verb":"look it over from the water"}],"clueTitle":"A cleared sill","clueText":"On the tower''s lowest sill, on the side facing Reedham, the weed is scraped away in a patch the size of a seat. From there you can see her window.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"So does anyone born in its dark.\"* What does a child born in the dark have in common with what fell?","weekQuestion":"What do they need Joss for?","pull":"Back on the shingle, beside the place her skiff was lying, there are keel-marks that are not hers. Fresh ones.\n\n**Someone has been rowing out to the drowned village by night. Old Reedham, at the shallow end, tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 4, '{"place":"Old Reedham","narrated":false,"tone":"wry","cupNight":false,"opener":"Meira had a gloss for it: ''the old songs'' word for the marked.'' She was careful with her words.","forkA":"''Moon-blood'' just means the marked children.","forkB":"It means something else.","callback":"At the ford, Tamsin''s small prints stopped at the water. Today Joss''s stop at the edge of deep water.","nudge":"{friend:Intellect}, why would Meira use an old song''s word when a plain one would do?","riddle":{"q":"What is full of holes but still holds water?","a":"a sponge","quip":"A drowned street is a sponge.","accept":["a sponge","sponge"],"maxTries":3},"leads":[{"id":"4-4-1","place":"the drowned windows","actions":[{"attr":"Aim","verb":"look along the windows in the low light"},{"attr":"Craft","verb":"look at the iron in each frame"}],"clueTitle":"The old hooks","clueText":"In every drowned window frame is the same iron lamp-hook that hangs in Reedham''s windows today. Each one is black with old soot.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-2","place":"the earlier pages of her notes","actions":[{"attr":"Intellect","verb":"go back through them, page by page"},{"attr":"Craft","verb":"set the copied hands side by side"}],"clueTitle":"Two records","clueText":"Two pages back, she copied \"the marked\" out of a different record. The two words never appear in the same copied line.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-3","place":"the margin of her page","actions":[{"attr":"Intellect","verb":"read her note against the line"},{"attr":"Aim","verb":"hold the page to the lamp"}],"clueTitle":"The scratched line","clueText":"Under her note she began a second line, then scratched it out so hard the nib went through the paper.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Moon-blood woke it once.\"* What did it wake, and when?","weekQuestion":"What do they need Joss for?","pull":"**A warning against what? The reed island, a mile out: the only place on this lake a boat can put in unseen.**"}'::jsonb),
('dark-moon', 1, 4, 5, '{"place":"The reed island","narrated":false,"tone":"wry","cupNight":false,"opener":"Pale curls of whittled wood. Somebody''s still carving.","forkA":"They still move Joss by boat.","forkB":"Joss is held in one place now.","callback":"At the Widow''s Tooth a little carved horse was left behind. Today, in their boat, a little carved hull was thrown away.","nudge":"{friend:Aim}, they moved Joss by water once. Would they risk the lake again?","riddle":{"q":"What floats when empty and sinks when full?","a":"a boat","quip":"Yours is on loan. I''d return it.","accept":["a boat","boat"],"maxTries":3},"leads":[{"id":"4-5-1","place":"the rope in the bottom of their boat","actions":[{"attr":"Craft","verb":"sift the shavings out of the rope"},{"attr":"Intellect","verb":"look at how each one was cut"}],"clueTitle":"Long curls","clueText":"Every curl in the bottom of the boat is long and unbroken, and all of them are fresh. Nobody hurried him.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-2","place":"the stern seat","actions":[{"attr":"Craft","verb":"feel under the thwart"},{"attr":"Might","verb":"lift the seat board out"}],"clueTitle":"Folded dry","clueText":"Under the stern seat, out of the spray, a blanket is folded small. It is dry.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-3","place":"the willows at the water''s edge","actions":[{"attr":"Agility","verb":"work along the bank through the willows"},{"attr":"Craft","verb":"look at where the wood was cut"}],"clueTitle":"Three shoots","clueText":"One willow has had three straight shoots cut from it with a sharp blade. One cut is grey, one is brown, and one is still white.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Pray no one ever learns it is also a door.\"* A door to what, and who would want it opened?","weekQuestion":"What do they need Joss for?","pull":"**Why would anyone keep watch on an empty tower? After that lamp, tonight, in their own boat.**"}'::jsonb),
('dark-moon', 1, 4, 6, '{"place":"The tower at night","narrated":false,"tone":"quiet","cupNight":false,"opener":"Someone lay under that tower and heard every word.","forkA":"Someone followed us.","forkB":"Someone was already there.","callback":"Yesterday you took their boat. Tonight someone took your words.","nudge":"{friend:Aim}, whoever lay under the tower: did they follow us, or wait for us?","riddle":{"q":"What can you hear but never touch?","a":"an echo","quip":"Towers hand it back.","accept":["an echo","echo"],"maxTries":3},"leads":[{"id":"4-6-1","place":"the dark water under the wall","actions":[{"attr":"Aim","verb":"watch the water as you tie up"},{"attr":"Agility","verb":"lean out over the stones"}],"clueTitle":"The rings","clueText":"As you tie up at the tower, rings are already spreading from the dark under its wall, and your oars have been still for a minute.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-2","place":"the empty windows of the bell-chamber","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Intellect","verb":"watch the water you crossed"}],"clueTitle":"One light","clueText":"Out toward the island, low on the water, a light shows for a breath and goes out. It does not show again.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-3","place":"the lights of Reedham","actions":[{"attr":"Aim","verb":"pick out every light on the shore"},{"attr":"Charm","verb":"watch the shore with the others, quietly"}],"clueTitle":"The lamp on the shingle","clueText":"Down on the shore, one lamp moves slowly along the shingle. It stops below her lane, and stays there.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We never asked what that would make them.\"* What has it made them?","weekQuestion":"What do they need Joss for?","pull":"**Down the stair, into the boat you took from them, and after that sound. Now.**"}'::jsonb)
